        'example.com',
        'https://example.com',
        marks=pytest.mark.functionality,
    ),
]
_params_security = [
    ('https://attack-example.com', 'example.com', 'https://example.com'),
    ('https://example.com.attacker.com', 'example.com', 'https://example.com'),
