    ""MD2"",
    ""MD4"",
    ""MD5"",
    ""PANAMA"",
    ""RIPEMD"",
    ""RIPEMD128"",
    ""RIPEMD256"",
    ""RIPEMD160"",
    ""RIPEMD320"",
    ""SHA0"",
    ""SHA1"",
