VALID_TOKEN = jwt.encode(PAYLOAD, SECRET_KEY, algorithm='HS256')
INVALID_TOKEN_0 = jwt.encode(PAYLOAD, 'wrongsecret', algorithm='HS256')
INVALID_TOKEN_1 = jwt.encode(PAYLOAD, SECRET_KEY, algorithm='HS512')


