        'https://example.com/api/user',
        'aBC123',
        'https://example.com/api/user/aBC123',
        marks=pytest.mark.functionality,
    ),
    pytest.param(
        'https://example.com/api/user',
        '',
        None,
        marks=pytest.mark.functionality,
